<?php
require_once dirname(__DIR__, 2) . '/config/config.php'; require_once dirname(__DIR__, 2) . '/config/database.php'; require_once dirname(__DIR__, 2) . '/config/functions.php'; require_once dirname(__DIR__, 2) . '/config/session.php'; require_once dirname(__DIR__, 2) . '/config/sponsor_assignments.php';
Session::start(); if (!Session::isLoggedIn()) { header('Location: ' . APP_URL . 'index.php'); exit(); } $role = Session::getUserRole(); if (!in_array($role, ['admin','vice_general_manager','general_manager','supervisor'], true)) { header('Location: ' . APP_URL . 'index.php'); exit(); }
$pageTitle=t('sponsors.title'); $active='sponsors'; $q=trim($_GET['q']??''); $fStatus=trim($_GET['status']??''); $fSup=(int)($_GET['sup']??0); $fLink=trim($_GET['link_status']??''); $page=max(1,(int)($_GET['page']??1)); $perPage=50;
$supervisors=dbFetchAll("SELECT u.id,u.full_name FROM users u JOIN roles r ON r.id=u.role_id WHERE r.code IN ('supervisor','admin','vice_general_manager') ORDER BY u.full_name");
$activeSponsorshipExists="EXISTS (SELECT 1 FROM sponsorships ss JOIN family_children fcc ON fcc.id=ss.child_id WHERE ss.sponsor_id=s.id AND ss.status='active')";
$activeSponsorshipCount="(SELECT COUNT(*) FROM sponsorships ss JOIN family_children fcc ON fcc.id=ss.child_id WHERE ss.sponsor_id=s.id AND ss.status='active')";
$sql="SELECT s.id,COALESCE(NULLIF(TRIM(s.sponsor_code),''),CONCAT('SP-',LPAD(s.id,6,'0'))) AS sponsor_code,s.full_name,s.phone,s.status,s.gender,s.supervisor_id,s.first_letter_id,$activeSponsorshipCount AS active_sponsorship_count FROM sponsors s WHERE 1=1"; $params=[];
if($role==='supervisor'){ $uid=Session::getUserId(); $scopeParts=['s.supervisor_id=?']; $scopeParams=[$uid]; $matrixRows=dbFetchAll("SELECT letter_id,gender FROM supervisor_letters WHERE supervisor_id=?",[$uid]); $letterGenderMap=[]; foreach($matrixRows as $matrixRow){$letterId=(int)$matrixRow['letter_id'];$rawGender=strtolower(trim((string)($matrixRow['gender']??'')));if(in_array($rawGender,['male','m','ذكر'],true))$gender='male';elseif(in_array($rawGender,['female','f','أنثى','انثى'],true))$gender='female';else$gender='both';$letterGenderMap[$letterId][]=$gender;} foreach($letterGenderMap as $letterId=>$genders){$genders=array_values(array_unique($genders));if(in_array('both',$genders,true)){$scopeParts[]='s.first_letter_id=?';$scopeParams[]=$letterId;continue;}$ph=implode(',',array_fill(0,count($genders),'?'));$scopeParts[]="(s.first_letter_id=? AND s.gender IN ($ph))";$scopeParams[]=$letterId;foreach($genders as $gender)$scopeParams[]=$gender;} $sql.=' AND ('.implode(' OR ',$scopeParts).')';$params=array_merge($params,$scopeParams);}elseif($fSup>0){$sql.=" AND s.supervisor_id=?";$params[]=$fSup;}
if($fStatus!==''){$sql.=" AND s.status=?";$params[]=$fStatus;} if($q!==''){$sql.=" AND (s.full_name LIKE ? OR s.sponsor_code LIKE ? OR s.phone LIKE ?)";$params[]="%$q%";$params[]="%$q%";$params[]="%$q%";}
if($fLink==='linked'){$sql.=" AND $activeSponsorshipExists";}elseif($fLink==='unlinked'){$sql.=" AND NOT $activeSponsorshipExists";}
$sql.=" ORDER BY s.id DESC"; $all=dbFetchAll($sql,$params); $total=count($all); $pages=max(1,(int)ceil($total/$perPage)); $page=min($page,$pages); $rows=array_slice($all,($page-1)*$perPage,$perPage); $qs=fn(array $extra)=>APP_URL.'modules/sponsors/index.php?'.http_build_query(array_merge($_GET,$extra)); $returnParams=[];if($q!=='')$returnParams['q']=$q;if($fStatus!=='')$returnParams['status']=$fStatus;if($fSup>0)$returnParams['sup']=$fSup;if($fLink!=='')$returnParams['link_status']=$fLink;$returnParams['page']=$page;$returnUrl=rawurlencode(http_build_query($returnParams)); include dirname(__DIR__,2).'/includes/header.php'; ?>
<div class="welcome-section fade-in"><h2><?php echo e(t('sponsors.title')); ?></h2><p><?php echo e(t('common.sponsors')); ?>: <?php echo $total; ?></p><div class="quick-actions mt-3"><?php if(in_array($role,['admin','vice_general_manager','supervisor'],true)): ?><a href="<?php echo APP_URL; ?>modules/sponsors/create.php" class="btn btn-primary btn-sm"><i class="fas fa-plus me-1"></i> <?php echo e(t('sponsors.add')); ?></a><a href="<?php echo APP_URL; ?>modules/sponsors/requests.php" class="btn btn-info btn-sm text-white"><i class="fas fa-bullhorn me-1"></i> <?php echo e(t('navigation.join_requests')); ?></a><?php endif; ?></div></div>
<div class="card mb-3 fade-in"><div class="card-body"><form method="get" class="row g-2 align-items-end"><div class="col-md-4"><label class="form-label"><?php echo e(t('common.search')); ?></label><input type="text" name="q" class="form-control" value="<?php echo e($q); ?>" placeholder="<?php echo e(t('search.placeholder')); ?>"></div><div class="col-md-2"><label class="form-label"><?php echo e(t('common.status')); ?></label><select name="status" class="form-select"><option value=""><?php echo e(t('common.all')); ?></option><option value="active" <?php echo $fStatus==='active'?'selected':''; ?>><?php echo e(t('common.active')); ?></option><option value="inactive" <?php echo $fStatus==='inactive'?'selected':''; ?>><?php echo e(t('common.inactive')); ?></option><option value="suspended" <?php echo $fStatus==='suspended'?'selected':''; ?>><?php echo e(t('common.paused')); ?></option><option value="cancelled" <?php echo $fStatus==='cancelled'?'selected':''; ?>><?php echo e(t('common.cancelled')); ?></option></select></div><div class="col-md-2"><label class="form-label">حالة الكفالة</label><select name="link_status" class="form-select"><option value=""><?php echo e(t('common.all')); ?></option><option value="linked" <?php echo $fLink==='linked'?'selected':''; ?>>مرتبط بكفالة</option><option value="unlinked" <?php echo $fLink==='unlinked'?'selected':''; ?>>غير مرتبط</option></select></div><?php if($role!=='supervisor'): ?><div class="col-md-2"><label class="form-label"><?php echo e(t('common.supervisors')); ?></label><select name="sup" class="form-select"><option value=""><?php echo e(t('common.all')); ?></option><?php foreach($supervisors as $s): ?><option value="<?php echo(int)$s['id']; ?>" <?php echo $fSup===(int)$s['id']?'selected':''; ?>><?php echo e($s['full_name']); ?></option><?php endforeach; ?></select></div><?php endif; ?><div class="col-md-2"><button class="btn btn-primary w-100"><i class="fas fa-search me-1"></i> <?php echo e(t('common.search')); ?></button></div></form></div></div>
<div class="card fade-in"><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>كود الكفيل</th><th>اسم الكفيل</th><th>الهاتف</th><th>حالة الكفالة</th><th><?php echo e(t('common.status')); ?></th><th class="text-center"><?php echo e(t('common.actions')); ?></th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="6" class="text-center text-muted py-4"><?php echo e(t('common.no_data')); ?></td></tr><?php else:foreach($rows as $r): ?><tr><td><?php echo e($r['sponsor_code']); ?></td><td><?php echo e($r['full_name']); ?></td><td dir="ltr"><?php echo e($r['phone']??'-'); ?></td><td><?php $activeSponsorships=(int)$r['active_sponsorship_count']; if($activeSponsorships>0): ?><span class="badge bg-success"><i class="fas fa-link me-1"></i> مرتبط — <?php echo $activeSponsorships; ?> كفالة نشطة</span><?php else: ?><span class="badge bg-warning text-dark"><i class="fas fa-unlink me-1"></i> غير مرتبط</span><?php endif; ?></td><td><?php $st=['active'=>['common.active','bg-success'],'inactive'=>['common.inactive','bg-secondary'],'suspended'=>['common.paused','bg-warning'],'cancelled'=>['common.cancelled','bg-danger']];[$sk,$sc]=$st[$r['status']]??[$r['status'],'bg-secondary']; ?><span class="badge <?php echo $sc; ?>"><?php echo e(t($sk)); ?></span></td><td class="text-center"><a class="btn btn-sm btn-primary" title="<?php echo e(t('common.view')); ?>" href="<?php echo APP_URL; ?>modules/sponsors/view.php?id=<?php echo(int)$r['id']; ?>&return=<?php echo $returnUrl; ?>"><i class="fas fa-eye"></i></a><?php if(in_array($role,['admin','vice_general_manager','supervisor'],true)): ?><a class="btn btn-sm btn-success" title="<?php echo e(t('common.payments')); ?>" href="<?php echo APP_URL; ?>modules/sponsors/view.php?id=<?php echo(int)$r['id']; ?>&return=<?php echo $returnUrl; ?>"><i class="fas fa-receipt"></i></a><?php endif; ?><?php if($role!=='general_manager'): ?><a class="btn btn-sm btn-warning" title="<?php echo e(t('common.edit')); ?>" href="<?php echo APP_URL; ?>modules/sponsors/edit.php?id=<?php echo(int)$r['id']; ?>&return=<?php echo $returnUrl; ?>"><i class="fas fa-pen"></i></a><?php endif; ?></td></tr><?php endforeach;endif; ?></tbody></table></div></div></div>
<?php if($pages>1): ?><nav class="mt-3 mb-4"><ul class="pagination justify-content-center"><?php for($i=1;$i<=$pages;$i++): ?><li class="page-item <?php echo $i===$page?'active':''; ?>"><a class="page-link" href="<?php echo e($qs(['page'=>$i])); ?>"><?php echo $i; ?></a></li><?php endfor; ?></ul></nav><?php endif; ?><?php include dirname(__DIR__,2).'/includes/footer.php'; ?>